 private static function need(bool $ok):void{if(!$ok)throw new DomainException('Ursprüngliche Kosten- und HGB-Journale selbst geschaffener Werte vollständig abstimmen.');}
 private static function keys(array $v,array $keys):bool{return count($v)===count($keys)&&!array_diff(array_keys($v),$keys);}
 private static function normal(mixed $v,?string $key=null):mixed{$object=is_object($v)||in_array($key,['cost_rows','original_cost_lines','original_book_lines','tax_links','book_links'],true);if(is_object($v))$v=get_object_vars($v);elseif(!is_array($v))return $v;$list=!$object&&array_is_list($v);if(!$list)ksort($v,SORT_STRING);foreach($v as $k=>&$x)$x=self::normal($x,is_string($k)?$k:null);unset($x);return $list?$v:(object)$v;}
