  self::need($depth>=0&&$depth<2&&isset($proof['source_proof'],$proof['book_source'])&&is_array($proof['source_proof'])&&is_array($proof['book_source'])&&array_key_exists('previous',$proof)&&($proof['previous']===null||is_array($proof['previous'])));$bp=OwnIntangibleBookBasis::calculate($proof['source_proof'],$proof['book_source'],$proof['previous']);self::need(self::hash($bp)===self::hash($proof));$proof=$bp;$s=$proof['source_proof']['source'];
  self::need(self::keys($j,['schema','club_id','item_id','year','period','account_key','result_account','chart','book_opening','book_entries','book_links','document','reason','confirmed'])&&$j['schema']===1&&$j['confirmed']===true&&is_int($j['year']));foreach(['book_links'] as $map)if(is_object($j[$map]))$j[$map]=get_object_vars($j[$map]);foreach(['club_id','item_id','period'] as $k)self::need($j[$k]===$s[$k]);self::need($j['period']===['start'=>$j['year'].'-01-01','end'=>$j['year'].'-12-31']);self::doc($j['document']);self::need(is_string($j['reason'])&&trim($j['reason'])!==''&&mb_strlen($j['reason'])<=2000&&!preg_match('/[\x00-\x1f]/',$j['reason']));
  $chart=BalanceCalculation::chart($j['chart']);$key=$j['account_key'];$resultKey=$j['result_account'];self::need(is_string($key)&&($chart[$key]['group']??null)==='fixed_assets'&&$chart[$key]['skr_code']===$s['account']&&is_string($resultKey)&&($chart[$resultKey]['group']??null)==='equity');
  if($previous===null)self::need($proof['previous']===null);
  else {
   self::need(isset($previous['book_proof'],$previous['journal'])&&is_array($previous['book_proof'])&&is_array($previous['journal'])&&array_key_exists('previous',$previous)&&($previous['previous']===null||is_array($previous['previous'])));$prior=self::verify($previous['book_proof'],$previous['journal'],$previous['previous'],$depth+1);self::need(self::hash($prior)===self::hash($previous)&&self::hash($proof['previous'])===self::hash($prior['book_proof'])&&$resultKey===$prior['journal']['result_account']);$previous=$prior;
   foreach($prior['journal']['chart'] as $k=>$v)self::need(($chart[$k]??null)===$v);
   foreach(['book'] as $side){$want=array_fill_keys(array_keys($chart),0);foreach(BalanceCalculation::carryForward($prior[$side.'_calculation'],$resultKey) as $line)$want[$line['account']]+=$line['debit_cents']-$line['credit_cents'];$actual=array_fill_keys(array_keys($chart),0);foreach($j[$side.'_opening'] as $line)$actual[$line['account']]+=$line['debit_cents']-$line['credit_cents'];self::need($want===$actual);}
  }
