  self::need($j['document']===$proof['book_source']['document']&&$j['reason']===$proof['book_source']['reason']&&(!in_array($chart[$resultKey]['skr_code'],['29000','29080'],true)||$book['annual_result_cents']===0));
  $entries=$costs=$fixed=[];foreach($j['book_entries'] as $e){self::need(is_array($e)&&is_string($e['id'])&&!isset($entries[$e['id']]));$entries[$e['id']]=$e;foreach($e['lines'] as $line)if($line['account']===$key)$fixed[$e['id']]=$e;}
  foreach($s['costs'] as $c){self::need(isset($entries[$c['journal_id']]));$e=$entries[$c['journal_id']];$ordinal=$c['line_ordinal'];self::need(isset($e['lines'][$ordinal]));$line=$e['lines'][$ordinal];self::need($chart[$line['account']]['group']==='expense'&&!in_array($chart[$line['account']]['skr_code'],['62010','62110','68960'],true)&&$line['credit_cents']===0&&$line['debit_cents']===$c['booked_cents']&&$e['date']===$c['on']&&($e['document']??null)===$c['document']);$rows=(array)$proof['source_proof']['cost_rows'];$costs[$c['id']]=['voucher'=>$e['id'],'line_ordinal'=>$ordinal,'original_expense_cents'=>$line['debit_cents'],'attributed_cents'=>$c['attributable_cents'],'capitalisation_eligible'=>$rows[$c['id']]['eligible']];}
