  foreach($j['book_links'] as $voucher=>$id){$original=$expected[$id];$e=$fixed[$voucher];self::need($e['date']===$original['on']&&($e['document']??null)===$original['document']&&count($e['lines'])===2);$own=$other=[];foreach($e['lines'] as $line){if($line['account']===$key)$own[]=$line;else $other[]=$line;}self::need(count($own)===1&&count($other)===1);$line=$own[0];$counter=$other[0];$positive=in_array($original['kind'],['capitalisation','writeup'],true);self::need([$line['debit_cents'],$line['credit_cents']]===($positive?[$original['amount_cents'],0]:[0,$original['amount_cents']])&&$chart[$counter['account']]['skr_code']===$original['counter_code']&&$chart[$counter['account']]['group']===($positive?'revenue':'expense'));$trace[$id]=['original'=>$e,'counter_key'=>$counter['account'],'book_change_cents'=>$line['debit_cents']-$line['credit_cents']];}
  self::need($book['accounts'][$key]['debit_cents']===$h['additions_cents']+$h['writeup_cents']&&$book['accounts'][$key]['credit_cents']===$h['amortisation_cents']+$h['impairment_cents']+$h['disposed_book_cents']);$j['book_links']=(object)$j['book_links'];
  $out=['schema'=>1,'book_proof'=>$proof,'journal'=>$j,'previous'=>$previous,'book_calculation'=>$book,'original_cost_lines'=>(object)$costs,'original_book_lines'=>(object)$trace,'journal_verified'=>true,'export_authorized'=>false];return $out+['sha256'=>self::hash($out)];
 }
}
